import re, pathlib
HERE = pathlib.Path(".")
def patch(fn, pairs):
    p = HERE / fn; s = p.read_text(encoding="utf-8")
    s = re.sub(r"(?<![A-Z])V\$", "GV$", s)          # V$ → GV$ (D03 제외)
    for old, new in pairs:
        assert s.count(old) >= 1, f"{fn}: 앵커 없음 → {old[:60]}"
        s = s.replace(old, new)
    p.write_text(s, encoding="utf-8", newline="\n"); print(fn, "ok")

