patch("D02_SCREEN_LOG_ASH_81.sql", [
 ("  JOIN GV$SQL_OPTIMIZER_ENV E ON E.SQL_ID = S.SQL_ID AND E.CHILD_NUMBER = S.CHILD_NUMBER AND E.ADDRESS = S.ADDRESS",
  "  JOIN GV$SQL_OPTIMIZER_ENV E ON E.INST_ID = S.INST_ID AND E.SQL_ID = S.SQL_ID AND E.CHILD_NUMBER = S.CHILD_NUMBER AND E.ADDRESS = S.ADDRESS"),
 ("  FROM GV$SESSION S JOIN GV$SES_OPTIMIZER_ENV E ON E.SID = S.SID", "  FROM GV$SESSION S JOIN GV$SES_OPTIMIZER_ENV E ON E.SID = S.SID AND E.INST_ID = S.INST_ID"),
 ("SELECT S.SQL_ID, S.CHILD_NUMBER CH, S.PROGRAM_LINE# LINE, S.PLAN_HASH_VALUE PHV, S.EXECUTIONS EX,\n       ROUND(S.ELAPSED_TIME/1e6/GREATEST(S.EXECUTIONS,1), 2) SEC_PER_EX,",
  "SELECT S.INST_ID INST, S.SQL_ID, S.CHILD_NUMBER CH, S.PROGRAM_LINE# LINE, S.PLAN_HASH_VALUE PHV, S.EXECUTIONS EX,\n       ROUND(S.ELAPSED_TIME/1e6/GREATEST(S.EXECUTIONS,1), 2) SEC_PER_EX,"),
 ("SELECT X.SESSION_ID SID, X.SESSION_SERIAL# SER,", "SELECT X.INST_ID INST, X.SESSION_ID SID, X.SESSION_SERIAL# SER,"),
 ("X AS (SELECT SESSION_ID, SESSION_SERIAL#, MIN(SAMPLE_TIME) T0, MAX(SAMPLE_TIME) T1, COUNT(*) SAMPLES, MAX(USER_ID) UID_, MAX(MACHINE) MACHINE\n        FROM A GROUP BY SESSION_ID, SESSION_SERIAL#),",
  "X AS (SELECT INST_ID, SESSION_ID, SESSION_SERIAL#, MIN(SAMPLE_TIME) T0, MAX(SAMPLE_TIME) T1, COUNT(*) SAMPLES, MAX(USER_ID) UID_, MAX(MACHINE) MACHINE\n        FROM A GROUP BY INST_ID, SESSION_ID, SESSION_SERIAL#),"),
 ("D AS (SELECT A.SESSION_ID, A.SESSION_SERIAL#, A.SQL_ID, COUNT(*) N,\n             ROW_NUMBER() OVER (PARTITION BY A.SESSION_ID, A.SESSION_SERIAL# ORDER BY COUNT(*) DESC) RN\n        FROM A GROUP BY A.SESSION_ID, A.SESSION_SERIAL#, A.SQL_ID)",
  "D AS (SELECT A.INST_ID, A.SESSION_ID, A.SESSION_SERIAL#, A.SQL_ID, COUNT(*) N,\n             ROW_NUMBER() OVER (PARTITION BY A.INST_ID, A.SESSION_ID, A.SESSION_SERIAL# ORDER BY COUNT(*) DESC) RN\n        FROM A GROUP BY A.INST_ID, A.SESSION_ID, A.SESSION_SERIAL#, A.SQL_ID)"),
 ("  FROM X LEFT JOIN D D1 ON D1.SESSION_ID = X.SESSION_ID AND D1.SESSION_SERIAL# = X.SESSION_SERIAL# AND D1.RN = 1\n         LEFT JOIN D D2 ON D2.SESSION_ID = X.SESSION_ID AND D2.SESSION_SERIAL# = X.SESSION_SERIAL# AND D2.RN = 2",
  "  FROM X LEFT JOIN D D1 ON D1.INST_ID = X.INST_ID AND D1.SESSION_ID = X.SESSION_ID AND D1.SESSION_SERIAL# = X.SESSION_SERIAL# AND D1.RN = 1\n         LEFT JOIN D D2 ON D2.INST_ID = X.INST_ID AND D2.SESSION_ID = X.SESSION_ID AND D2.SESSION_SERIAL# = X.SESSION_SERIAL# AND D2.RN = 2"),
])
